var ENT=[["Haystack", "Production retrieval pipelines."], ["sentence-transformers", "Standard embedding library."], ["Pinecone", "Managed vector DB for production RAG."], ["BEIR", "Zero-shot retrieval benchmark suite."], ["LlamaIndex", "Data framework connecting LLMs to documents via indexes, retrievers and query engines."], ["Chroma", "A developer-friendly open-source embedding database for RAG prototypes."], ["Qdrant", "A Rust-based vector search engine with filtering and hybrid search."]];
var TECH=[["Chunking strategies", "Splitting documents into retrievable units: fixed, semantic or hierarchical."], ["Embedding indexing", "Storing chunk vectors for sub-second similarity search."], ["Hybrid retrieval", "Combining BM25 keyword and vector scores before reranking."], ["Reranking", "Applying a stronger cross-encoder to the top-k candidates for precision."], ["Citation grounding", "Forcing answers to quote or cite the retrieved passages used."], ["Query rewriting", "Expanding or decomposing user questions into better retrieval queries."], ["Context stuffing budgets", "Packing the most relevant chunks without overflowing the window."], ["Metadata filtering", "Restricting retrieval by date, source or permissions before ranking."], ["Faithfulness checks", "Verifying generated claims are entailed by retrieved context."], ["Index refresh pipelines", "Re-embedding changed documents so answers stay current."]];
